(function(){
  var P = AutoJS.players()[0];
  var L = AutoJS.level();
  var CSU = Java.loadClass('com.merlinkitsune.astral_dice.item.CurioSlotUtil');
  var MSI = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.MosesSignItem');
  var ME = Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
  var Eff = Java.loadClass('com.merlinkitsune.astral_dice.platform.util.Effects');
  var MEI = Java.loadClass('net.minecraft.world.effect.MobEffectInstance');
  var WRE = Java.loadClass('com.merlinkitsune.astral_dice.effect.WeaknessRevealEffect');
  var gmm = new RegExp('"gameMode":"([a-z_]+)"').exec(String(AutoJS.state()));
  var gmName = gmm === null ? 'creative' : gmm[1];
  AutoJS.write('astral_test_state.txt', gmName + '|' + P.getX() + '|' + P.getY() + '|' + P.getZ());
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  AutoJS.command('gamemode survival @a');
  var out = {};
  out.diceEquipped = CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:diamond_dice', 1), 'dice').getResult().consumesAction();
  out.signEquipped = CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:moses_sign', 1), 'stand').getResult().consumesAction();
  out.mosesEquipped = MSI.isEquipped(P);
  P.setHealth(P.getMaxHealth());
  var zombie = AutoJS.summon('minecraft:zombie', P.getX() + 2.0, P.getY(), P.getZ());
  zombie.setNoAi(true);
  zombie.addEffect(new MEI(Eff.holder(ME.MOSES_BROKEN.get()), 600, 0));
  out.zombieHasBroken = zombie.hasEffect(Eff.holder(ME.MOSES_BROKEN.get()));
  WRE.removeAll(P);
  var hpBefore = P.getHealth();
  var res = P.hurt(L.damageSources().mobAttack(zombie), 4.0);
  out.hurtResult = res;
  out.playerHealthDelta = hpBefore - P.getHealth();
  out.zombieHealthDelta = zombie.getMaxHealth() - zombie.getHealth();
  out.zombieAlive = zombie.isAlive();
  out.weaknessStacksAfter = WRE.getStacks(P);
  out.playerHealthAfter = P.getHealth();
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var DCI = Java.loadClass('com.merlinkitsune.astral_dice.item.dice.DiceCurioItem');
  var WRE = Java.loadClass('com.merlinkitsune.astral_dice.effect.WeaknessRevealEffect');
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  var stp0 = String(AutoJS.read('astral_test_state.txt')).split('|');
  var gm = stp0[0];
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('effect clear @a');
  AutoJS.command('clear @a');
  WRE.removeAll(P);
  var inv = Cur.getCuriosInventory(P).get();
  inv.getStacksHandler('stand').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  inv.getStacksHandler('dice').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  DCI.refreshChipSlotCount(P);
  AutoJS.command('gamemode ' + gm + ' @a');
  P.setHealth(P.getMaxHealth());
  return {
    gameModeRestored: String(AutoJS.state()).indexOf('"gameMode":"' + gm + '"') >= 0,
    diceSlotEmptyAfter: inv.getStacksHandler('dice').get().getStacks().getStackInSlot(0).isEmpty(),
    standSlotEmptyAfter: inv.getStacksHandler('stand').get().getStacks().getStackInSlot(0).isEmpty(),
    chipSlotsFinal: inv.getStacksHandler('chip').get().getSlots(),
    weaknessFinal: WRE.getStacks(P)
  };
})()
